def sid(x):return pre+'source:'+x
def entity(id,label,kind,role,refs):return dict(id=pre+'entity:'+id,label=label,kind=kind,role=role,sourceIds=[sid(s) for s in refs])
def link(id,fr,to,kind,label,refs,status='documented'):return dict(id=pre+'link:'+id,**{'from':pre+'entity:'+fr,'to':pre+'entity:'+to},kind=kind,label=label,sourceIds=[sid(s) for s in refs],status=status)
def statement(text,*refs):return dict(text=text,sourceIds=[sid(s) for s in refs])
