import re
def spaces(v):
 if isinstance(v,dict):return {k:(val if k in ['id','sourceIds','url','from','to','cityIds','stateCodes','sectors','family','kind','status','date','publishedAt','retrievedAt','updatedAt','evaluationAt','cutoff'] else spaces(val)) for k,val in v.items()}
 if isinstance(v,list):return [spaces(a) for a in v]
 if isinstance(v,str):return re.sub(r'(?<=[a-zA-Z])(?=\d)|(?<=\d)(?=[a-zA-Z])',' ',v)
 return v
